using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 renamed the default discriminator property from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents remain readable and
        // direct SQL queries (WHERE c.Discriminator = ...) keep working.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed the default id format from "EntityType|Key" to just "Key".
        // Preserve the old format so existing documents are still addressable.
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Id);
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal.IdValueGenerator>();

        modelBuilder.Entity<Product>().ToContainer("Products");

        // HasIndex is not supported on Cosmos DB and now throws in EF Core 9.
        // Removed: modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

